INSERT INTO consultation (case_id, consulted_at, category, category_etc, purpose, content, recorder_member_id, created_at, updated_at)
SELECT c.case_id, s.consulted_at::date, s.category, s.category_etc, s.purpose, s.content, m.member_id,
       s.created_at::timestamp AT TIME ZONE 'Asia/Seoul', s.created_at::timestamp AT TIME ZONE 'Asia/Seoul'
FROM (VALUES
    ('chuncheon', '2025-0001', '임정호', '1947-08-16', '2025-07-11', '초기상담', NULL, '치매 의심 어르신 첫 방문', '같은 물건을 반복해서 사 오고 가스불을 켜 둔 채 외출한 일이 있다는 이웃 제보. 혼자 사는 어르신으로 자녀는 멀리 살아 자주 오지 못함.', 'demo2@demo-chuncheon.eumi.test', '2025-07-11 18:59'),
    ('chuncheon', '2025-0001', '임정호', '1947-08-16', '2026-05-27', '긴급상담', NULL, '귀가 지연으로 긴급 대응', '어르신이 저녁까지 귀가하지 않아 자녀가 실종 신고. 이웃 동네에서 무사히 발견됨. 배회 감지기 지원을 신청하고 안부 확인을 매일로 늘림.', 'demo2@demo-chuncheon.eumi.test', '2026-05-27 14:37'),
    ('chuncheon', '2025-0001', '임정호', '1947-08-16', '2026-09-21', '정기상담', NULL, '안전 점검 방문', '가스 자동차단기를 설치하고 약 달력을 드림. 생활지원사 방문 횟수를 늘림.', 'demo1@demo-chuncheon.eumi.test', '2026-09-21 18:07'),
    ('chuncheon', '2025-0002', '송미영', '1972-04-06', '2025-07-16', '초기상담', NULL, '장애 자녀 돌봄 가구 상담', '성인이 된 발달장애 자녀를 돌보는 부모. 나이가 들어 돌봄이 버겁고, 자녀가 낮에 갈 곳이 없어 집에만 있음.', 'demo1@demo-chuncheon.eumi.test', '2025-07-16 16:55'),
    ('chuncheon', '2025-0002', '송미영', '1972-04-06', '2026-05-11', '기타', '사례회의', '통합사례회의', '주민센터 · 정신건강복지센터와 사례회의를 열어 역할을 나눔. 이 기관은 정기 방문과 자원 연계를, 주민센터는 공적 급여 신청을 맡기로 함.', 'demo1@demo-chuncheon.eumi.test', '2026-05-11 17:09'),
    ('chuncheon', '2025-0002', '송미영', '1972-04-06', '2026-10-21', '긴급상담', NULL, '보호자 입원으로 돌봄 공백', '보호자가 갑자기 입원하게 되어 돌봄 공백이 생김. 단기보호를 연계하고 가족과 돌봄 일정을 조율함.', 'demo1@demo-chuncheon.eumi.test', '2026-10-21 17:21'),
    ('chuncheon', '2025-0003', '이현주', '1963-09-25', '2025-08-07', '초기상담', NULL, '주거환경 악화 가구 첫 방문', '집 안에 물건과 쓰레기가 쌓여 악취가 난다는 이웃 민원으로 방문. 혼자 사는 어르신으로 물건을 버리는 것을 강하게 거부함. 화재 위험이 있어 단계적으로 정리하기로 설득함.', 'demo2@demo-chuncheon.eumi.test', '2025-08-07 15:19'),
    ('chuncheon', '2025-0003', '이현주', '1963-09-25', '2026-08-27', '정기상담', NULL, '주거환경 정리 1차', '본인 동의를 받아 부엌과 현관부터 정리. 버릴 물건은 본인이 직접 고르게 함. 정리 후 숨이 좀 쉬어진다고 함.', 'demo2@demo-chuncheon.eumi.test', '2026-08-27 17:03'),
    ('chuncheon', '2025-0004', '박정례', '1940-04-08', '2025-08-12', '초기상담', NULL, '마을 이장 의뢰로 첫 방문', '혼자 사는 고령 어르신. 읍내로 가는 버스가 하루 세 번뿐이라 병원과 장보기가 어려움. 무릎이 아파 마을회관에도 잘 나가지 않음. 자녀는 서울에 살며 한 달에 한 번 방문.', 'demo1@demo-chuncheon.eumi.test', '2025-08-12 13:47'),
    ('chuncheon', '2025-0004', '박정례', '1940-04-08', '2025-10-02', '정기상담', NULL, '돌봄 서비스 연계', '노인맞춤돌봄 서비스를 연계해 생활지원사가 주 2회 방문하기로 함. 약 배달과 병원 동행 일정을 정함.', 'demo1@demo-chuncheon.eumi.test', '2025-10-02 16:02'),
    ('chuncheon', '2025-0004', '박정례', '1940-04-08', '2025-12-18', '긴급상담', NULL, '한파 중 보일러 고장', '생활지원사가 보일러 고장을 발견해 연락함. 긴급 수리를 연계하고 수리 전까지 전기난로를 지원. 겨울철 주간 안부 확인을 늘림.', 'demo2@demo-chuncheon.eumi.test', '2025-12-18 18:15'),
    ('chuncheon', '2025-0004', '박정례', '1940-04-08', '2026-02-26', '정기상담', NULL, '이동 목욕 서비스 연결', '겨울 내내 목욕을 못 하셨다고 해 찾아가는 이동 목욕을 신청함. 첫 이용 후 만족해하심.', 'demo1@demo-chuncheon.eumi.test', '2026-02-26 15:21'),
    ('chuncheon', '2025-0004', '박정례', '1940-04-08', '2026-08-06', '정기상담', NULL, '폭염 안부 확인', '폭염 기간 하루 한 번 안부 전화를 진행. 낮에는 마을회관 무더위 쉼터를 이용하시도록 안내.', 'demo2@demo-chuncheon.eumi.test', '2026-08-06 16:30'),
    ('chuncheon', '2025-0004', '박정례', '1940-04-08', '2026-10-28', '정기상담', NULL, '겨울철 대비 방문', '보일러를 미리 점검하고 난방유 지원을 신청함. 이동 목욕을 월 2회 이용 중이며 마을회관 점심 모임에도 가끔 나가심.', 'demo1@demo-chuncheon.eumi.test', '2026-10-28 16:13'),
    ('chuncheon', '2025-0005', '김덕수', '1952-09-30', '2025-09-23', '초기상담', NULL, '배우자 사별 후 고립 우려', '올해 초 배우자와 사별한 뒤 농사를 그만두고 집에만 있음. 낮부터 술을 마시는 날이 늘었고 끼니를 자주 거름. 이웃이 걱정해 연락함.', 'demo1@demo-chuncheon.eumi.test', '2025-09-23 14:18'),
    ('chuncheon', '2025-0005', '김덕수', '1952-09-30', '2025-11-04', '정기상담', NULL, '음주와 식사 점검', '음주 상담은 원하지 않아 강요하지 않기로 함. 반찬 배달을 연계하고 마을 공동 밥상을 안내함.', 'demo1@demo-chuncheon.eumi.test', '2025-11-04 18:59'),
    ('chuncheon', '2025-0005', '김덕수', '1952-09-30', '2026-01-15', '긴급상담', NULL, '이웃 신고: 며칠째 인기척 없음', '이웃이 며칠째 인기척이 없다고 신고. 방문하니 술을 마시고 쓰러져 있었으나 의식은 있었음. 응급진료를 받게 하고 자녀에게 연락.', 'demo1@demo-chuncheon.eumi.test', '2026-01-15 13:24'),
    ('chuncheon', '2025-0005', '김덕수', '1952-09-30', '2026-04-02', '중기상담', NULL, '공동 밥상 참여 후 변화', '마을 공동 밥상에 주 3회 나오기 시작함. 음주가 줄었다고 본인이 이야기함. 텃밭 가꾸기를 다시 해 보겠다고 함.', 'demo1@demo-chuncheon.eumi.test', '2026-04-02 17:51'),
    ('chuncheon', '2025-0005', '김덕수', '1952-09-30', '2026-10-20', '정기상담', NULL, '공동 밥상 참여 점검', '공동 밥상에 꾸준히 나오고 텃밭에서 기른 채소를 나누기 시작함. 음주는 주말에만 한다고 함. 자녀와 한 달에 한 번 통화하기로 함.', 'demo1@demo-chuncheon.eumi.test', '2026-10-20 17:37'),
    ('chuncheon', '2025-0006', '김진호', '1980-11-03', '2025-09-25', '초기상담', NULL, '중장년 1인가구 첫 상담', '오래된 단독주택에 혼자 사는 중장년 남성. 사업을 접은 뒤 일용직을 전전하다 최근 몇 달은 일이 끊김. 하루 대부분을 집에서 보내고 끼니는 라면으로 때움. 가족과는 연락하지 않는다고 함.', 'demo2@demo-chuncheon.eumi.test', '2025-09-25 18:06'),
    ('chuncheon', '2025-0006', '김진호', '1980-11-03', '2025-12-08', '정기상담', NULL, '구직 상담 연계', '고용센터 중장년 취업 상담 예약을 함께 잡음. 이력서 작성을 어려워해 다음 방문 때 같이 쓰기로 함.', 'demo1@demo-chuncheon.eumi.test', '2025-12-08 14:18'),
    ('chuncheon', '2025-0006', '김진호', '1980-11-03', '2026-05-28', '종료상담', NULL, '사례 종결 상담', '정규직으로 취업해 생활이 안정됨. 체납도 모두 해소되어 본인 동의로 종결. 어려움이 생기면 언제든 연락하도록 안내함.', 'demo2@demo-chuncheon.eumi.test', '2026-05-28 13:00'),
    ('chuncheon', '2025-0007', '이춘길', '1944-12-05', '2025-10-21', '초기상담', NULL, '고령 부부 돌봄 부담', '치매 초기인 배우자를 혼자 돌보고 있음. 본인도 고령이라 체력이 떨어지고 바깥 활동을 전혀 못 함. 산골 마을이라 이웃과 거리가 멂.', 'demo2@demo-chuncheon.eumi.test', '2025-10-21 17:01'),
    ('chuncheon', '2025-0007', '이춘길', '1944-12-05', '2025-12-02', '정기상담', NULL, '장기요양 등급 신청', '배우자의 장기요양 등급 신청을 도움. 주야간 돌봄 차량 지원을 안내함.', 'demo2@demo-chuncheon.eumi.test', '2025-12-02 18:14'),
    ('chuncheon', '2025-0007', '이춘길', '1944-12-05', '2026-03-17', '중기상담', NULL, '주야간보호 이용 후 점검', '배우자가 주 3회 주야간보호를 이용하기 시작해 돌봄 부담이 줄었다고 함. 본인은 경로당 모임에 다시 나가기 시작함.', 'demo2@demo-chuncheon.eumi.test', '2026-03-17 13:49'),
    ('chuncheon', '2025-0007', '이춘길', '1944-12-05', '2026-10-13', '긴급상담', NULL, '배우자 야간 배회', '배우자가 밤중에 집을 나가려 해 잠을 못 잤다는 연락. 배회 감지기를 신청하고 야간 돌봄 부담을 덜도록 단기보호 이용을 안내함.', 'demo2@demo-chuncheon.eumi.test', '2026-10-13 13:50'),
    ('chuncheon', '2025-0008', '안기석', '1950-07-08', '2025-10-27', '초기상담', NULL, '치매 의심 어르신 첫 방문', '같은 물건을 반복해서 사 오고 가스불을 켜 둔 채 외출한 일이 있다는 이웃 제보. 혼자 사는 어르신으로 자녀는 멀리 살아 자주 오지 못함.', 'demo1@demo-chuncheon.eumi.test', '2025-10-27 17:02'),
    ('chuncheon', '2025-0008', '안기석', '1950-07-08', '2025-12-29', '정기상담', NULL, '안전 점검 방문', '가스 자동차단기를 설치하고 약 달력을 드림. 생활지원사 방문 횟수를 늘림.', 'demo2@demo-chuncheon.eumi.test', '2025-12-29 15:17'),
    ('chuncheon', '2025-0008', '안기석', '1950-07-08', '2026-05-04', '중기상담', NULL, '진단 후 돌봄 계획 점검', '경도 치매 진단을 받음. 치매안심센터 인지 프로그램에 주 2회 참여 중이며 자녀가 주말마다 방문하기로 함.', 'demo1@demo-chuncheon.eumi.test', '2026-05-04 18:19'),
    ('chuncheon', '2025-0008', '안기석', '1950-07-08', '2026-10-19', '긴급상담', NULL, '귀가 지연으로 긴급 대응', '어르신이 저녁까지 귀가하지 않아 자녀가 실종 신고. 이웃 동네에서 무사히 발견됨. 배회 감지기 지원을 신청하고 안부 확인을 매일로 늘림.', 'demo2@demo-chuncheon.eumi.test', '2026-10-19 14:52'),
    ('chuncheon', '2025-0009', '김경자', '1952-02-10', '2025-11-06', '초기상담', NULL, '이웃 제보로 첫 방문', '같은 건물 이웃이 요즘 어르신이 보이지 않는다고 알려 와 방문. 배우자와 사별한 뒤 혼자 지내며 낮에도 커튼을 치고 TV만 본다고 함. 혈압약은 챙기고 있으나 식사량이 눈에 띄게 줄었음.', 'demo1@demo-chuncheon.eumi.test', '2025-11-06 15:36'),
    ('chuncheon', '2025-0009', '김경자', '1952-02-10', '2026-03-17', '정기상담', NULL, '돌봄 서비스 연계 점검', '노인맞춤돌봄 생활지원사가 주 2회 방문 중이며 만족도가 높음. 복약은 규칙적. 외출은 여전히 적어 복지관 모임에 함께 가 보기로 함.', 'demo1@demo-chuncheon.eumi.test', '2026-03-17 15:20'),
    ('chuncheon', '2025-0009', '김경자', '1952-02-10', '2026-10-19', '정기상담', NULL, '전화 안부 확인', '전화로 안부 확인. 날씨 때문에 외출을 줄였다고 함. 난방과 식사 상태를 확인하고 다음 주 방문을 약속함.', 'demo1@demo-chuncheon.eumi.test', '2026-10-19 14:07'),
    ('chuncheon', '2025-0010', '박만수', '1942-05-01', '2025-11-10', '초기상담', NULL, '독거 어르신 안부 확인 첫 방문', '오래된 단독주택에서 혼자 지내는 어르신. 자녀와는 연락이 뜸하고 최근 몇 달 사이 외출이 크게 줄었다고 함. 무릎과 허리 통증으로 장보기가 어려워 끼니를 자주 거름. 방문을 반기며 정기 방문에 동의함.', 'demo2@demo-chuncheon.eumi.test', '2025-11-10 17:36'),
    ('chuncheon', '2025-0010', '박만수', '1942-05-01', '2026-01-27', '긴급상담', NULL, '낙상 후 긴급 방문', '집 안에서 넘어져 손목을 다쳤다는 연락을 받고 방문. 병원 진료에 동행했고 골절은 아님. 회복 기간 동안 반찬 배달과 안부 전화를 매일로 늘림.', 'demo2@demo-chuncheon.eumi.test', '2026-01-27 14:06'),
    ('chuncheon', '2025-0010', '박만수', '1942-05-01', '2026-02-09', '긴급상담', NULL, '며칠째 연락 두절', '사흘째 전화를 받지 않아 방문. 감기로 누워 있었고 식사를 거의 하지 못함. 진료를 연계하고 긴급 도시락을 지원함.', 'demo2@demo-chuncheon.eumi.test', '2026-02-09 13:37'),
    ('chuncheon', '2025-0010', '박만수', '1942-05-01', '2026-05-25', '종료상담', NULL, '사례 종결 상담', '요양시설 입소가 결정되어 사례를 종결함. 입소 서류 준비를 도왔고 보호자에게 이후 연락처를 안내함.', 'demo1@demo-chuncheon.eumi.test', '2026-05-25 16:26'),
    ('chuncheon', '2025-0011', '전수아', '2010-09-26', '2025-11-14', '초기상담', NULL, '조손가정 청소년 상담', '할머니와 둘이 사는 청소년. 학교 결석이 잦아 담임교사가 의뢰함. 할머니 건강이 나빠져 집안일과 병원 동행을 대신 하고 있음.', 'demo1@demo-chuncheon.eumi.test', '2025-11-14 14:01'),
    ('chuncheon', '2025-0011', '전수아', '2010-09-26', '2026-03-25', '정기상담', NULL, '학교 · 가정 연계 상담', '담임교사와 통화해 출결 상황을 공유함. 청소년상담복지센터 상담과 온라인 학습 지원을 연계함.', 'demo1@demo-chuncheon.eumi.test', '2026-03-25 16:14'),
    ('chuncheon', '2025-0011', '전수아', '2010-09-26', '2026-08-31', '중기상담', NULL, '진로 상담', '관심 있는 요리 분야 직업체험을 연계함. 표정이 밝아지고 친구 이야기를 하기 시작함.', 'demo1@demo-chuncheon.eumi.test', '2026-08-31 18:45'),
    ('chuncheon', '2025-0011', '전수아', '2010-09-26', '2026-09-15', '종료상담', NULL, '사례 종결 상담', '친척이 함께 살게 되고 학교생활이 안정되어 종결.', 'demo1@demo-chuncheon.eumi.test', '2026-09-15 14:05'),
    ('chuncheon', '2025-0012', '이만수', '1940-04-14', '2025-11-24', '초기상담', NULL, '고령 부부 가구 첫 방문', '고령 부부가 함께 사는데 배우자의 거동이 불편해 어르신 혼자 돌보고 있음. 장보기와 병원 이동이 가장 큰 어려움이라고 함. 겨울철 기름보일러 난방비 부담이 큼.', 'demo1@demo-chuncheon.eumi.test', '2025-11-24 18:24'),
    ('chuncheon', '2025-0012', '이만수', '1940-04-14', '2026-10-26', '정기상담', NULL, '농한기 생활 점검', '겨울에는 집 밖에 거의 나가지 않는다고 함. 난방유 지원을 신청하고 이웃 주민에게 하루 한 번 들여다봐 주기를 부탁함.', 'demo1@demo-chuncheon.eumi.test', '2026-10-26 17:13'),
    ('chuncheon', '2025-0013', '윤영희', '1947-04-06', '2025-11-28', '초기상담', NULL, '마을 이장 의뢰로 첫 방문', '버스가 하루 몇 차례뿐인 마을에서 혼자 지내는 어르신. 농사를 그만둔 뒤 마을회관에도 잘 나가지 않음. 병원은 자녀가 올 때만 다녀와 진료가 자주 밀림.', 'demo1@demo-chuncheon.eumi.test', '2025-11-28 14:25'),
    ('chuncheon', '2025-0013', '윤영희', '1947-04-06', '2026-02-11', '정기상담', NULL, '농한기 생활 점검', '겨울에는 집 밖에 거의 나가지 않는다고 함. 난방유 지원을 신청하고 이웃 주민에게 하루 한 번 들여다봐 주기를 부탁함.', 'demo1@demo-chuncheon.eumi.test', '2026-02-11 18:44'),
    ('chuncheon', '2025-0013', '윤영희', '1947-04-06', '2026-08-24', '중기상담', NULL, '지원 연계 후 점검', '생활지원사가 주 2회 방문하고 병원 동행 차량을 월 2회 이용 중. 마을회관 건강체조에도 나가기 시작함.', 'demo1@demo-chuncheon.eumi.test', '2026-08-24 17:08'),
    ('chuncheon', '2026-0001', '박정호', '1953-02-24', '2026-01-26', '초기상담', NULL, '가족 돌봄 부담 상담', '치매 진단을 받은 배우자를 혼자 돌보는 중. 밤에 배우자가 자주 깨어 잠을 거의 못 잔다고 함. 본인도 지병이 있으나 병원에 갈 틈이 없음.', 'demo2@demo-chuncheon.eumi.test', '2026-01-26 17:29'),
    ('chuncheon', '2026-0001', '박정호', '1953-02-24', '2026-05-08', '기타', '동행지원', '병원 진료 동행', '진료에 동행해 의사 설명을 쉽게 다시 정리해 드림. 다음 진료 예약과 약 복용 방법을 메모로 남겨 드림.', 'demo2@demo-chuncheon.eumi.test', '2026-05-08 15:39'),
    ('chuncheon', '2026-0001', '박정호', '1953-02-24', '2026-09-17', '정기상담', NULL, '돌봄 서비스 연계', '장기요양 등급과 활동지원 서비스 신청 절차를 안내하고 서류 준비를 도움. 주간보호 기관 몇 곳을 함께 알아봄.', 'demo2@demo-chuncheon.eumi.test', '2026-09-17 14:36'),
    ('chuncheon', '2026-0002', '김복순', '1944-02-13', '2026-02-13', '초기상담', NULL, '고령 부부 가구 첫 방문', '고령 부부가 함께 사는데 배우자의 거동이 불편해 어르신 혼자 돌보고 있음. 장보기와 병원 이동이 가장 큰 어려움이라고 함. 겨울철 기름보일러 난방비 부담이 큼.', 'demo1@demo-chuncheon.eumi.test', '2026-02-13 17:19'),
    ('chuncheon', '2026-0002', '김복순', '1944-02-13', '2026-04-09', '긴급상담', NULL, '보일러 고장', '한파 중 보일러가 멈췄다는 연락. 긴급 수리를 연계하고 수리 전까지 전기난로를 지원함.', 'demo2@demo-chuncheon.eumi.test', '2026-04-09 14:47'),
    ('chuncheon', '2026-0002', '김복순', '1944-02-13', '2026-08-24', '정기상담', NULL, '정기 방문 및 건강 확인', '혈압과 복약 상태 확인. 병원 동행 차량 이용을 안내했고 다음 진료일에 이용해 보기로 함. 마을회관 점심 모임 참여를 권함.', 'demo1@demo-chuncheon.eumi.test', '2026-08-24 15:24'),
    ('chuncheon', '2026-0002', '김복순', '1944-02-13', '2026-10-28', '정기상담', NULL, '농한기 생활 점검', '겨울에는 집 밖에 거의 나가지 않는다고 함. 난방유 지원을 신청하고 이웃 주민에게 하루 한 번 들여다봐 주기를 부탁함.', 'demo2@demo-chuncheon.eumi.test', '2026-10-28 13:24'),
    ('chuncheon', '2026-0003', '김봉순', '1938-01-18', '2026-03-03', '초기상담', NULL, '치매 의심 어르신 첫 방문', '같은 물건을 반복해서 사 오고 가스불을 켜 둔 채 외출한 일이 있다는 이웃 제보. 혼자 사는 어르신으로 자녀는 멀리 살아 자주 오지 못함.', 'demo2@demo-chuncheon.eumi.test', '2026-03-03 13:02'),
    ('chuncheon', '2026-0003', '김봉순', '1938-01-18', '2026-05-11', '정기상담', NULL, '안전 점검 방문', '가스 자동차단기를 설치하고 약 달력을 드림. 생활지원사 방문 횟수를 늘림.', 'demo1@demo-chuncheon.eumi.test', '2026-05-11 17:42'),
    ('chuncheon', '2026-0003', '김봉순', '1938-01-18', '2026-06-15', '기타', '사례회의', '통합사례회의', '주민센터 · 정신건강복지센터와 사례회의를 열어 역할을 나눔. 이 기관은 정기 방문과 자원 연계를, 주민센터는 공적 급여 신청을 맡기로 함.', 'demo1@demo-chuncheon.eumi.test', '2026-06-15 14:37'),
    ('chuncheon', '2026-0003', '김봉순', '1938-01-18', '2026-07-13', '중기상담', NULL, '진단 후 돌봄 계획 점검', '경도 치매 진단을 받음. 치매안심센터 인지 프로그램에 주 2회 참여 중이며 자녀가 주말마다 방문하기로 함.', 'demo1@demo-chuncheon.eumi.test', '2026-07-13 14:15'),
    ('chuncheon', '2026-0003', '김봉순', '1938-01-18', '2026-07-30', '종료상담', NULL, '사례 종결 상담', '장기요양 등급을 받아 방문요양 서비스로 전환되어 종결. 요양기관 담당자에게 그간 상황을 인계함.', 'demo2@demo-chuncheon.eumi.test', '2026-07-30 14:08'),
    ('chuncheon', '2026-0004', '이태현', '1994-08-15', '2026-03-12', '초기상담', NULL, '고립 청년 첫 상담', '임대아파트에 혼자 사는 청년. 퇴사 후 반년째 외출은 편의점이 전부라고 함. 연락하는 친구가 없고 식사는 배달 음식 위주. 메시지 상담에는 응함.', 'demo1@demo-chuncheon.eumi.test', '2026-03-12 13:29'),
    ('chuncheon', '2026-0004', '이태현', '1994-08-15', '2026-10-05', '정기상담', NULL, '방문 상담', '처음으로 얼굴을 보고 이야기함. 방 정리가 되어 있지 않아 함께 정리 계획을 세움. 청년 지원 프로그램 안내지를 전달.', 'demo1@demo-chuncheon.eumi.test', '2026-10-05 16:54'),
    ('chuncheon', '2026-0005', '신봉순', '1939-04-01', '2026-03-16', '초기상담', NULL, '마을 이장 의뢰로 첫 방문', '버스가 하루 몇 차례뿐인 마을에서 혼자 지내는 어르신. 농사를 그만둔 뒤 마을회관에도 잘 나가지 않음. 병원은 자녀가 올 때만 다녀와 진료가 자주 밀림.', 'demo1@demo-chuncheon.eumi.test', '2026-03-16 15:38'),
    ('chuncheon', '2026-0005', '신봉순', '1939-04-01', '2026-05-13', '정기상담', NULL, '농한기 생활 점검', '겨울에는 집 밖에 거의 나가지 않는다고 함. 난방유 지원을 신청하고 이웃 주민에게 하루 한 번 들여다봐 주기를 부탁함.', 'demo1@demo-chuncheon.eumi.test', '2026-05-13 13:34'),
    ('chuncheon', '2026-0005', '신봉순', '1939-04-01', '2026-06-15', '중기상담', NULL, '지원 연계 후 점검', '생활지원사가 주 2회 방문하고 병원 동행 차량을 월 2회 이용 중. 마을회관 건강체조에도 나가기 시작함.', 'demo1@demo-chuncheon.eumi.test', '2026-06-15 15:13'),
    ('chuncheon', '2026-0005', '신봉순', '1939-04-01', '2026-10-12', '종료상담', NULL, '사례 종결 상담', '자녀가 모시기로 해 도시로 이사함. 그동안의 지원 내용을 정리해 전입지 주민센터에 연계함.', 'demo1@demo-chuncheon.eumi.test', '2026-10-12 17:41'),
    ('chuncheon', '2026-0006', '조상우', '1977-04-18', '2026-03-16', '초기상담', NULL, '고독사 위험 가구 조사 후 첫 방문', '관리비가 석 달째 밀려 있다는 연락을 받고 방문. 이혼 후 혼자 지내며 음주가 잦고 수면이 불규칙함. 처음에는 상담을 거부했으나 두 번째 방문에서 이야기를 시작함.', 'demo1@demo-chuncheon.eumi.test', '2026-03-16 17:28'),
    ('chuncheon', '2026-0006', '조상우', '1977-04-18', '2026-06-11', '정기상담', NULL, '생활 상황 점검', '식사와 수면 상태를 확인함. 긴급복지 생계지원 신청을 도왔고 결과를 함께 기다리기로 함. 주 1회 안부 전화에 동의.', 'demo1@demo-chuncheon.eumi.test', '2026-06-11 14:02'),
    ('chuncheon', '2026-0006', '조상우', '1977-04-18', '2026-06-15', '정기상담', NULL, '구직 상담 연계', '고용센터 중장년 취업 상담 예약을 함께 잡음. 이력서 작성을 어려워해 다음 방문 때 같이 쓰기로 함.', 'demo1@demo-chuncheon.eumi.test', '2026-06-15 17:02'),
    ('chuncheon', '2026-0006', '조상우', '1977-04-18', '2026-11-02', '종료상담', NULL, '사례 종결 상담', '정규직으로 취업해 생활이 안정됨. 체납도 모두 해소되어 본인 동의로 종결. 어려움이 생기면 언제든 연락하도록 안내함.', 'demo1@demo-chuncheon.eumi.test', '2026-11-02 14:41'),
    ('chuncheon', '2026-0007', '이유진', '1993-08-08', '2026-04-01', '초기상담', NULL, '한부모 가구 첫 상담', '혼자 초등학생 자녀 둘을 키우는 한부모 가구. 식당 일을 하다 손목을 다쳐 일을 쉬고 있음. 자녀 방과 후 돌봄이 어렵고 본인도 우울감을 호소함.', 'demo2@demo-chuncheon.eumi.test', '2026-04-01 18:17'),
    ('chuncheon', '2026-0007', '이유진', '1993-08-08', '2026-06-29', '정기상담', NULL, '정기 상담', '손목 치료를 받으며 재취업을 준비 중. 자녀들은 지역아동센터에 잘 적응함. 본인 휴식 시간이 부족하다고 함.', 'demo1@demo-chuncheon.eumi.test', '2026-06-29 16:24'),
    ('chuncheon', '2026-0007', '이유진', '1993-08-08', '2026-09-14', '정기상담', NULL, '지원 신청 진행 점검', '한부모가족 아동양육비 신청을 마침. 지역아동센터 이용을 연계해 방과 후 돌봄 걱정을 덜었음.', 'demo2@demo-chuncheon.eumi.test', '2026-09-14 16:02'),
    ('chuncheon', '2026-0008', '이성훈', '1972-08-04', '2026-04-27', '초기상담', NULL, '가족 돌봄 부담 상담', '치매 진단을 받은 배우자를 혼자 돌보는 중. 밤에 배우자가 자주 깨어 잠을 거의 못 잔다고 함. 본인도 지병이 있으나 병원에 갈 틈이 없음.', 'demo1@demo-chuncheon.eumi.test', '2026-04-27 13:36'),
    ('chuncheon', '2026-0008', '이성훈', '1972-08-04', '2026-08-10', '정기상담', NULL, '보호자 상태 점검', '주간보호 이용 후 낮 시간에 쉴 수 있게 됨. 미뤄 둔 본인 진료를 다녀옴.', 'demo1@demo-chuncheon.eumi.test', '2026-08-10 15:10'),
    ('chuncheon', '2026-0008', '이성훈', '1972-08-04', '2026-09-28', '정기상담', NULL, '돌봄 서비스 연계', '장기요양 등급과 활동지원 서비스 신청 절차를 안내하고 서류 준비를 도움. 주간보호 기관 몇 곳을 함께 알아봄.', 'demo1@demo-chuncheon.eumi.test', '2026-09-28 18:37'),
    ('chuncheon', '2026-0009', '이지혜', '2005-02-11', '2026-04-27', '초기상담', NULL, '고립 청년 첫 상담', '오래된 단독주택에 혼자 사는 청년. 퇴사 후 반년째 외출은 편의점이 전부라고 함. 연락하는 친구가 없고 식사는 배달 음식 위주. 메시지 상담에는 응함.', 'demo1@demo-chuncheon.eumi.test', '2026-04-27 17:45'),
    ('chuncheon', '2026-0009', '이지혜', '2005-02-11', '2026-09-24', '기타', '동행지원', '병원 진료 동행', '진료에 동행해 의사 설명을 쉽게 다시 정리해 드림. 다음 진료 예약과 약 복용 방법을 메모로 남겨 드림.', 'demo1@demo-chuncheon.eumi.test', '2026-09-24 18:02'),
    ('chuncheon', '2026-0009', '이지혜', '2005-02-11', '2026-10-08', '정기상담', NULL, '메시지 상담', '주 2회 메시지로 근황을 나눔. 잠드는 시간이 조금 앞당겨졌다고 함. 하루 10분 산책을 목표로 정함.', 'demo1@demo-chuncheon.eumi.test', '2026-10-08 18:51'),
    ('chuncheon', '2026-0010', '이경수', '1963-09-19', '2026-06-22', '초기상담', NULL, '중장년 1인가구 첫 상담', '오래된 단독주택에 혼자 사는 중장년 남성. 사업을 접은 뒤 일용직을 전전하다 최근 몇 달은 일이 끊김. 하루 대부분을 집에서 보내고 끼니는 라면으로 때움. 가족과는 연락하지 않는다고 함.', 'demo1@demo-chuncheon.eumi.test', '2026-06-22 14:28'),
    ('chuncheon', '2026-0010', '이경수', '1963-09-19', '2026-08-11', '기타', '사례회의', '통합사례회의', '주민센터 · 정신건강복지센터와 사례회의를 열어 역할을 나눔. 이 기관은 정기 방문과 자원 연계를, 주민센터는 공적 급여 신청을 맡기로 함.', 'demo1@demo-chuncheon.eumi.test', '2026-08-11 18:53'),
    ('chuncheon', '2026-0010', '이경수', '1963-09-19', '2026-09-08', '정기상담', NULL, '생활 상황 점검', '식사와 수면 상태를 확인함. 긴급복지 생계지원 신청을 도왔고 결과를 함께 기다리기로 함. 주 1회 안부 전화에 동의.', 'demo1@demo-chuncheon.eumi.test', '2026-09-08 13:40'),
    ('chuncheon', '2026-0010', '이경수', '1963-09-19', '2026-09-29', '정기상담', NULL, '구직 상담 연계', '고용센터 중장년 취업 상담 예약을 함께 잡음. 이력서 작성을 어려워해 다음 방문 때 같이 쓰기로 함.', 'demo1@demo-chuncheon.eumi.test', '2026-09-29 13:42'),
    ('chuncheon', '2026-0010', '이경수', '1963-09-19', '2026-10-05', '긴급상담', NULL, '단전 예고 통지', '전기요금 체납으로 단전 예고장을 받았다고 연락. 긴급 지원으로 체납액을 해결하고 분할 납부를 안내함.', 'demo1@demo-chuncheon.eumi.test', '2026-10-05 14:30'),
    ('chuncheon', '2026-0011', '최옥자', '1945-03-28', '2026-07-06', '초기상담', NULL, '치매 의심 어르신 첫 방문', '같은 물건을 반복해서 사 오고 가스불을 켜 둔 채 외출한 일이 있다는 이웃 제보. 혼자 사는 어르신으로 자녀는 멀리 살아 자주 오지 못함.', 'demo1@demo-chuncheon.eumi.test', '2026-07-06 18:14'),
    ('chuncheon', '2026-0011', '최옥자', '1945-03-28', '2026-09-17', '긴급상담', NULL, '귀가 지연으로 긴급 대응', '어르신이 저녁까지 귀가하지 않아 자녀가 실종 신고. 이웃 동네에서 무사히 발견됨. 배회 감지기 지원을 신청하고 안부 확인을 매일로 늘림.', 'demo1@demo-chuncheon.eumi.test', '2026-09-17 14:51'),
    ('chuncheon', '2026-0011', '최옥자', '1945-03-28', '2026-10-22', '정기상담', NULL, '치매 선별검사 연계', '치매안심센터 선별검사에 동행함. 정밀검사가 필요하다는 결과가 나와 자녀와 일정을 조율함.', 'demo1@demo-chuncheon.eumi.test', '2026-10-22 18:33'),
    ('gangnam', '2025-0001', '안정숙', '1948-09-05', '2025-06-06', '초기상담', NULL, '주거환경 악화 가구 첫 방문', '집 안에 물건과 쓰레기가 쌓여 악취가 난다는 이웃 민원으로 방문. 혼자 사는 어르신으로 물건을 버리는 것을 강하게 거부함. 화재 위험이 있어 단계적으로 정리하기로 설득함.', 'demo1@demo-gangnam.eumi.test', '2025-06-06 16:01'),
    ('gangnam', '2025-0001', '안정숙', '1948-09-05', '2025-08-19', '긴급상담', NULL, '화재 위험 신고', '집 안에서 타는 냄새가 난다는 신고로 소방이 출동함. 큰불은 아니었으나 전열기구 주변에 물건이 쌓여 있었음. 긴급 정리와 전기 안전 점검을 연계함.', 'demo1@demo-gangnam.eumi.test', '2025-08-19 14:48'),
    ('gangnam', '2025-0001', '안정숙', '1948-09-05', '2025-11-26', '정기상담', NULL, '정리 후 유지 점검', '정리한 공간이 대체로 유지되고 있음. 주 1회 방문해 함께 정리 상태를 확인하기로 함.', 'demo1@demo-gangnam.eumi.test', '2025-11-26 18:01'),
    ('gangnam', '2025-0001', '안정숙', '1948-09-05', '2026-09-28', '기타', '가족상담', '가족과 돌봄 계획 논의', '가족과 통화해 그간 상황을 공유함. 가족이 한 달에 한 번 방문하고 주 1회 전화하기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-09-28 18:12'),
    ('gangnam', '2025-0002', '오정훈', '1958-03-14', '2025-08-21', '초기상담', NULL, '고립 위험 가구 발굴 조사 후 첫 방문', '퇴직 후 3년째 혼자 거주. 이웃과 교류가 거의 없고 가족과는 명절에만 통화함. 낮에 자고 밤에 깨어 있는 생활로 주중과 주말 구분 없이 지냄. 식사는 배달 음식과 편의점 위주이며 고혈압 약을 불규칙하게 복용. 처음에는 방문을 경계했으나 다음 방문에 동의함.', 'demo1@demo-gangnam.eumi.test', '2025-08-21 15:54'),
    ('gangnam', '2025-0002', '오정훈', '1958-03-14', '2025-09-18', '정기상담', NULL, '생활 리듬과 식사 점검', '복약 달력을 드리고 주 1회 안부 전화에 동의받음. 중장년 남성 요리교실을 안내했으나 낯선 사람과 어울리는 것이 부담스럽다며 망설임. 다음 방문 때 프로그램 담당자와 함께 오기로 함.', 'demo1@demo-gangnam.eumi.test', '2025-09-18 17:45'),
    ('gangnam', '2025-0002', '오정훈', '1958-03-14', '2025-11-06', '긴급상담', NULL, '안부 전화 3일 미응답', '3일 연속 전화를 받지 않아 통장과 함께 방문. 감기 몸살로 이틀째 누워 있었고 식사를 거의 하지 못한 상태. 병원 진료에 동행하고 긴급 도시락을 1주일 연계함. 공동 담당자와 방문 주기를 주 2회로 늘리기로 협의.', 'demo2@demo-gangnam.eumi.test', '2025-11-06 17:50'),
    ('gangnam', '2025-0002', '오정훈', '1958-03-14', '2025-12-15', '정기상담', NULL, '회복 후 사회관계 연결', '건강을 회복했고 요리교실 첫 참여 의사를 밝힘. 이웃 안부 살피미 활동가와 연결해 주 1회 방문을 시작하기로 함. 밤낮이 바뀐 생활을 줄이기 위해 오전 산책 목표를 함께 정함.', 'demo1@demo-gangnam.eumi.test', '2025-12-15 18:41'),
    ('gangnam', '2025-0002', '오정훈', '1958-03-14', '2026-03-12', '중기상담', NULL, '프로그램 참여 점검', '요리교실 8회 중 6회 참석. 같은 동 참여자와 연락을 주고받기 시작함. 늦은 밤 활동이 줄고 평일 오전 외출이 늘었다고 함. 복약도 규칙적으로 유지 중.', 'demo1@demo-gangnam.eumi.test', '2026-03-12 15:57'),
    ('gangnam', '2025-0002', '오정훈', '1958-03-14', '2026-09-24', '정기상담', NULL, '분기 점검', '주 2회 복지관을 이용하며 생활이 안정됨. 다음 목표로 중장년 자조모임 참여를 함께 정함. 안부 전화는 격주로 줄이기로 합의.', 'demo2@demo-gangnam.eumi.test', '2026-09-24 14:25'),
    ('gangnam', '2025-0003', '한순자', '1946-11-02', '2025-09-04', '초기상담', NULL, '낙상 이후 외출 감소 의뢰 접수', '혼자 사는 어르신으로 지난봄 계단에서 넘어진 뒤 외출을 거의 하지 않음. 자녀는 해외에 거주. 평일에는 요양보호사가 다녀가지만 주말에는 아무도 오지 않아 하루 종일 혼자 지냄. 무릎 통증과 불안감을 호소.', 'demo1@demo-gangnam.eumi.test', '2025-09-04 17:32'),
    ('gangnam', '2025-0003', '한순자', '1946-11-02', '2025-10-16', '정기상담', NULL, '방문간호와 안전 점검', '방문간호를 연계하고 욕실 안전손잡이 설치를 신청함. 주말 안부 전화를 시작하기로 함.', 'demo1@demo-gangnam.eumi.test', '2025-10-16 13:03'),
    ('gangnam', '2025-0003', '한순자', '1946-11-02', '2025-12-22', '긴급상담', NULL, '한파 대비 난방비 문의', '난방비 부담으로 보일러를 거의 켜지 않고 있었음. 에너지바우처 신청을 돕고 전기요 지원을 연계함.', 'demo1@demo-gangnam.eumi.test', '2025-12-22 13:27'),
    ('gangnam', '2025-0003', '한순자', '1946-11-02', '2026-04-09', '정기상담', NULL, '주말 활동 연결', '주말 어르신 걷기 모임에 동행해 첫 참여. 다리 상태가 좋아져 주 1회 모임 참여를 이어가기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-04-09 18:10'),
    ('gangnam', '2025-0003', '한순자', '1946-11-02', '2026-10-15', '정기상담', NULL, '겨울 준비 점검', '걷기 모임에 꾸준히 나가 다리 힘이 붙었다고 함. 지난겨울 난방비 문제가 있었던 만큼 에너지바우처 재신청과 보일러 점검 일정을 미리 잡음.', 'demo1@demo-gangnam.eumi.test', '2026-10-15 15:57'),
    ('gangnam', '2025-0004', '윤재석', '1970-06-20', '2025-10-02', '초기상담', NULL, '실직 후 고립 중장년 상담', '1년 전 실직 후 이혼해 원룸에서 혼자 생활. 구직을 포기한 상태로 하루 대부분을 집에서 보냄. 수면이 불규칙하고 우울감을 호소. 월세가 두 달 밀려 있음.', 'demo1@demo-gangnam.eumi.test', '2025-10-02 17:29'),
    ('gangnam', '2025-0004', '윤재석', '1970-06-20', '2025-11-13', '정기상담', NULL, '정신건강 상담 연계', '정신건강복지센터 상담에 동의해 첫 예약을 잡음. 긴급생계지원 신청을 안내함.', 'demo1@demo-gangnam.eumi.test', '2025-11-13 16:31'),
    ('gangnam', '2025-0004', '윤재석', '1970-06-20', '2026-01-22', '중기상담', NULL, '재취업 준비 점검', '상담을 4회 받았고 수면이 나아짐. 중장년 재취업 상담 창구에 등록해 직업훈련 과정을 알아보는 중.', 'demo1@demo-gangnam.eumi.test', '2026-01-22 16:33'),
    ('gangnam', '2025-0004', '윤재석', '1970-06-20', '2026-06-18', '정기상담', NULL, '취업 후 생활 점검', '물류센터 시간제 일자리를 구함. 월세 체납은 해소. 동네 자조모임에 한 달에 한 번 나가기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-06-18 14:09'),
    ('gangnam', '2025-0004', '윤재석', '1970-06-20', '2026-10-22', '종료상담', NULL, '사례 종결 상담', '시간제 일자리가 정규직으로 전환됨. 자조모임에는 계속 나가기로 했고 본인 동의로 사례를 종결함. 어려움이 생기면 언제든 다시 연락하도록 안내.', 'demo1@demo-gangnam.eumi.test', '2026-10-22 13:39'),
    ('gangnam', '2025-0005', '최성민', '2003-01-10', '2025-10-23', '초기상담', NULL, '청년 1인가구 생활고 상담', '고시원에 사는 청년. 아르바이트가 끊겨 월세가 두 달 밀림. 학자금 대출 상환 독촉을 받고 있으며 식비를 아끼려고 하루 한 끼만 먹는다고 함.', 'demo2@demo-gangnam.eumi.test', '2025-10-23 13:24'),
    ('gangnam', '2025-0005', '최성민', '2003-01-10', '2026-01-12', '정기상담', NULL, '주거 · 금융 지원 연계', '청년 월세 지원과 재무상담을 안내하고 신청을 도움. 푸드뱅크 이용을 연계함.', 'demo2@demo-gangnam.eumi.test', '2026-01-12 17:15'),
    ('gangnam', '2025-0005', '최성민', '2003-01-10', '2026-03-02', '긴급상담', NULL, '퇴거 통보', '월세 체납으로 이번 달 말까지 방을 비우라는 통보를 받음. 긴급 주거비를 신청하고 임시 거처를 함께 알아봄.', 'demo2@demo-gangnam.eumi.test', '2026-03-02 17:33'),
    ('gangnam', '2025-0005', '최성민', '2003-01-10', '2026-08-25', '중기상담', NULL, '지원 이후 변화 점검', '재무상담을 받고 대출 상환 일정을 조정함. 청년 임대주택 청약을 준비 중.', 'demo2@demo-gangnam.eumi.test', '2026-08-25 15:14'),
    ('gangnam', '2025-0006', '정민우', '1997-02-11', '2025-11-07', '기타', '가족상담', '부모 의뢰로 시작한 은둔 청년 상담', '부모와 함께 살지만 2년째 방에서 거의 나오지 않음. 식사는 방 앞에 두면 가져감. 대학 졸업 후 취업에 실패한 뒤 친구 연락도 끊음. 부모가 지쳐 있어 가족 상담부터 진행.', 'demo2@demo-gangnam.eumi.test', '2025-11-07 18:26'),
    ('gangnam', '2025-0006', '정민우', '1997-02-11', '2025-12-11', '초기상담', NULL, '본인 첫 대면', '문을 사이에 두고 짧게 대화. 밤새 게임을 하고 낮에 잠. 직접 만나는 것은 거절했지만 메시지 상담에는 동의함.', 'demo2@demo-gangnam.eumi.test', '2025-12-11 15:07'),
    ('gangnam', '2025-0006', '정민우', '1997-02-11', '2026-02-05', '정기상담', NULL, '메시지 상담 진행 점검', '주 2회 메시지 상담을 이어가는 중. 청년 마음 쉼터 상담실 방문을 한 번 해 보겠다고 함.', 'demo1@demo-gangnam.eumi.test', '2026-02-05 16:56'),
    ('gangnam', '2025-0006', '정민우', '1997-02-11', '2026-05-14', '중기상담', NULL, '외부 활동 시작', '청년 마음 쉼터에 세 번 방문. 비슷한 처지의 청년 모임에 관심을 보임. 부모와 저녁 식사를 함께하기 시작함.', 'demo1@demo-gangnam.eumi.test', '2026-05-14 15:35'),
    ('gangnam', '2025-0006', '정민우', '1997-02-11', '2026-09-03', '기타', '가족상담', '부모 상담', '부모가 아들이 저녁 식사 자리에 거의 매일 나온다며 변화에 안도함. 재촉하지 말고 지금 속도를 지켜 주기로 이야기함.', 'demo2@demo-gangnam.eumi.test', '2026-09-03 18:52'),
    ('gangnam', '2025-0006', '정민우', '1997-02-11', '2026-10-29', '정기상담', NULL, '청년 모임 참여 점검', '청년 모임에 한 달째 매주 참여 중. 단기 아르바이트를 알아보고 있어 청년 일자리 상담을 연계하기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-10-29 14:29'),
    ('gangnam', '2025-0007', '박수빈', '1995-07-20', '2025-11-10', '초기상담', NULL, '한부모 가구 첫 상담', '혼자 초등학생 자녀 둘을 키우는 한부모 가구. 식당 일을 하다 손목을 다쳐 일을 쉬고 있음. 자녀 방과 후 돌봄이 어렵고 본인도 우울감을 호소함.', 'demo1@demo-gangnam.eumi.test', '2025-11-10 16:21'),
    ('gangnam', '2025-0007', '박수빈', '1995-07-20', '2026-01-12', '정기상담', NULL, '정기 상담', '손목 치료를 받으며 재취업을 준비 중. 자녀들은 지역아동센터에 잘 적응함. 본인 휴식 시간이 부족하다고 함.', 'demo1@demo-gangnam.eumi.test', '2026-01-12 17:05'),
    ('gangnam', '2025-0007', '박수빈', '1995-07-20', '2026-09-07', '정기상담', NULL, '지원 신청 진행 점검', '한부모가족 아동양육비 신청을 마침. 지역아동센터 이용을 연계해 방과 후 돌봄 걱정을 덜었음.', 'demo1@demo-gangnam.eumi.test', '2026-09-07 15:30'),
    ('gangnam', '2025-0008', '윤옥순', '1939-02-15', '2025-11-17', '초기상담', NULL, '치매 의심 어르신 첫 방문', '같은 물건을 반복해서 사 오고 가스불을 켜 둔 채 외출한 일이 있다는 이웃 제보. 혼자 사는 어르신으로 자녀는 멀리 살아 자주 오지 못함.', 'demo1@demo-gangnam.eumi.test', '2025-11-17 16:46'),
    ('gangnam', '2025-0008', '윤옥순', '1939-02-15', '2026-04-13', '긴급상담', NULL, '귀가 지연으로 긴급 대응', '어르신이 저녁까지 귀가하지 않아 자녀가 실종 신고. 이웃 동네에서 무사히 발견됨. 배회 감지기 지원을 신청하고 안부 확인을 매일로 늘림.', 'demo1@demo-gangnam.eumi.test', '2026-04-13 16:05'),
    ('gangnam', '2025-0008', '윤옥순', '1939-02-15', '2026-08-06', '정기상담', NULL, '치매 선별검사 연계', '치매안심센터 선별검사에 동행함. 정밀검사가 필요하다는 결과가 나와 자녀와 일정을 조율함.', 'demo1@demo-gangnam.eumi.test', '2026-08-06 18:41'),
    ('gangnam', '2025-0008', '윤옥순', '1939-02-15', '2026-09-02', '정기상담', NULL, '안전 점검 방문', '가스 자동차단기를 설치하고 약 달력을 드림. 생활지원사 방문 횟수를 늘림.', 'demo1@demo-gangnam.eumi.test', '2026-09-02 13:35'),
    ('gangnam', '2025-0009', '황현우', '2000-05-06', '2025-12-05', '초기상담', NULL, '가족 의뢰로 시작한 은둔 청년 상담', '부모와 함께 살지만 1년 넘게 방에서 거의 나오지 않음. 낮과 밤이 바뀐 생활을 하며 가족과 대화가 끊김. 부모 상담부터 시작하기로 함.', 'demo1@demo-gangnam.eumi.test', '2025-12-05 13:24'),
    ('gangnam', '2025-0009', '황현우', '2000-05-06', '2026-07-23', '긴급상담', NULL, '위기 메시지 수신', '늦은 밤 다 그만두고 싶다는 메시지를 받음. 바로 통화해 안전을 확인하고 다음 날 정신건강복지센터 긴급 상담을 연계함. 가족에게도 상황을 알림.', 'demo1@demo-gangnam.eumi.test', '2026-07-23 15:44'),
    ('gangnam', '2025-0009', '황현우', '2000-05-06', '2026-09-30', '정기상담', NULL, '메시지 상담', '주 2회 메시지로 근황을 나눔. 잠드는 시간이 조금 앞당겨졌다고 함. 하루 10분 산책을 목표로 정함.', 'demo1@demo-gangnam.eumi.test', '2026-09-30 14:20'),
    ('gangnam', '2026-0001', '박미영', '1986-07-08', '2026-01-15', '초기상담', NULL, '한부모 가구 첫 상담', '혼자 초등학생 자녀 둘을 키우는 한부모 가구. 식당 일을 하다 손목을 다쳐 일을 쉬고 있음. 자녀 방과 후 돌봄이 어렵고 본인도 우울감을 호소함.', 'demo1@demo-gangnam.eumi.test', '2026-01-15 14:33'),
    ('gangnam', '2026-0001', '박미영', '1986-07-08', '2026-03-19', '기타', '가족상담', '가족과 돌봄 계획 논의', '가족과 통화해 그간 상황을 공유함. 가족이 한 달에 한 번 방문하고 주 1회 전화하기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-03-19 14:57'),
    ('gangnam', '2026-0001', '박미영', '1986-07-08', '2026-04-09', '정기상담', NULL, '지원 신청 진행 점검', '한부모가족 아동양육비 신청을 마침. 지역아동센터 이용을 연계해 방과 후 돌봄 걱정을 덜었음.', 'demo1@demo-gangnam.eumi.test', '2026-04-09 14:38'),
    ('gangnam', '2026-0001', '박미영', '1986-07-08', '2026-10-29', '긴급상담', NULL, '자녀 입원으로 긴급 지원', '자녀가 폐렴으로 입원해 병원비와 다른 자녀 돌봄이 급함. 긴급 의료비를 신청하고 아이돌봄 서비스를 연계함.', 'demo1@demo-gangnam.eumi.test', '2026-10-29 13:31'),
    ('gangnam', '2026-0002', '권수진', '1965-06-28', '2026-02-02', '초기상담', NULL, '가족 돌봄 부담 상담', '치매 진단을 받은 배우자를 혼자 돌보는 중. 밤에 배우자가 자주 깨어 잠을 거의 못 잔다고 함. 본인도 지병이 있으나 병원에 갈 틈이 없음.', 'demo2@demo-gangnam.eumi.test', '2026-02-02 14:39'),
    ('gangnam', '2026-0002', '권수진', '1965-06-28', '2026-08-24', '정기상담', NULL, '보호자 상태 점검', '주간보호 이용 후 낮 시간에 쉴 수 있게 됨. 미뤄 둔 본인 진료를 다녀옴.', 'demo2@demo-gangnam.eumi.test', '2026-08-24 18:39'),
    ('gangnam', '2026-0002', '권수진', '1965-06-28', '2026-11-02', '종료상담', NULL, '사례 종결 상담', '돌봄 대상 가족이 시설에 입소해 보호자 부담이 줄어 종결. 보호자 건강관리를 위해 보건소 프로그램을 안내함.', 'demo2@demo-gangnam.eumi.test', '2026-11-02 15:41'),
    ('gangnam', '2026-0003', '이영자', '1952-07-15', '2026-02-02', '초기상담', NULL, '주거환경 악화 가구 첫 방문', '집 안에 물건과 쓰레기가 쌓여 악취가 난다는 이웃 민원으로 방문. 혼자 사는 어르신으로 물건을 버리는 것을 강하게 거부함. 화재 위험이 있어 단계적으로 정리하기로 설득함.', 'demo1@demo-gangnam.eumi.test', '2026-02-02 14:07'),
    ('gangnam', '2026-0003', '이영자', '1952-07-15', '2026-07-20', '긴급상담', NULL, '화재 위험 신고', '집 안에서 타는 냄새가 난다는 신고로 소방이 출동함. 큰불은 아니었으나 전열기구 주변에 물건이 쌓여 있었음. 긴급 정리와 전기 안전 점검을 연계함.', 'demo1@demo-gangnam.eumi.test', '2026-07-20 16:59'),
    ('gangnam', '2026-0003', '이영자', '1952-07-15', '2026-08-31', '정기상담', NULL, '정리 후 유지 점검', '정리한 공간이 대체로 유지되고 있음. 주 1회 방문해 함께 정리 상태를 확인하기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-08-31 16:59'),
    ('gangnam', '2026-0004', '조수진', '1978-04-28', '2026-03-09', '초기상담', NULL, '한부모 가구 첫 상담', '혼자 초등학생 자녀 둘을 키우는 한부모 가구. 식당 일을 하다 손목을 다쳐 일을 쉬고 있음. 자녀 방과 후 돌봄이 어렵고 본인도 우울감을 호소함.', 'demo1@demo-gangnam.eumi.test', '2026-03-09 17:12'),
    ('gangnam', '2026-0004', '조수진', '1978-04-28', '2026-08-27', '정기상담', NULL, '정기 상담', '손목 치료를 받으며 재취업을 준비 중. 자녀들은 지역아동센터에 잘 적응함. 본인 휴식 시간이 부족하다고 함.', 'demo1@demo-gangnam.eumi.test', '2026-08-27 13:10'),
    ('gangnam', '2026-0004', '조수진', '1978-04-28', '2026-10-15', '정기상담', NULL, '지원 신청 진행 점검', '한부모가족 아동양육비 신청을 마침. 지역아동센터 이용을 연계해 방과 후 돌봄 걱정을 덜었음.', 'demo1@demo-gangnam.eumi.test', '2026-10-15 14:59'),
    ('gangnam', '2026-0005', '박태식', '1966-07-05', '2026-03-16', '초기상담', NULL, '고독사 위험 가구 조사 후 첫 방문', '관리비가 석 달째 밀려 있다는 연락을 받고 방문. 이혼 후 혼자 지내며 음주가 잦고 수면이 불규칙함. 처음에는 상담을 거부했으나 두 번째 방문에서 이야기를 시작함.', 'demo1@demo-gangnam.eumi.test', '2026-03-16 17:07'),
    ('gangnam', '2026-0005', '박태식', '1966-07-05', '2026-09-21', '정기상담', NULL, '생활 상황 점검', '식사와 수면 상태를 확인함. 긴급복지 생계지원 신청을 도왔고 결과를 함께 기다리기로 함. 주 1회 안부 전화에 동의.', 'demo1@demo-gangnam.eumi.test', '2026-09-21 17:33'),
    ('gangnam', '2026-0006', '김유진', '2002-01-22', '2026-03-27', '초기상담', NULL, '청년 1인가구 생활고 상담', '고시원에 사는 청년. 아르바이트가 끊겨 월세가 두 달 밀림. 학자금 대출 상환 독촉을 받고 있으며 식비를 아끼려고 하루 한 끼만 먹는다고 함.', 'demo1@demo-gangnam.eumi.test', '2026-03-27 16:46'),
    ('gangnam', '2026-0006', '김유진', '2002-01-22', '2026-05-18', '긴급상담', NULL, '퇴거 통보', '월세 체납으로 이번 달 말까지 방을 비우라는 통보를 받음. 긴급 주거비를 신청하고 임시 거처를 함께 알아봄.', 'demo2@demo-gangnam.eumi.test', '2026-05-18 15:34'),
    ('gangnam', '2026-0006', '김유진', '2002-01-22', '2026-09-08', '정기상담', NULL, '생활 점검', '단기 일자리를 구해 주 4일 일하는 중. 식사는 하루 두 끼로 늘었음. 남은 체납 월세 상환 계획을 함께 세움.', 'demo2@demo-gangnam.eumi.test', '2026-09-08 14:02'),
    ('gangnam', '2026-0007', '김예린', '2012-09-18', '2026-04-06', '초기상담', NULL, '조손가정 청소년 상담', '할머니와 둘이 사는 청소년. 학교 결석이 잦아 담임교사가 의뢰함. 할머니 건강이 나빠져 집안일과 병원 동행을 대신 하고 있음.', 'demo1@demo-gangnam.eumi.test', '2026-04-06 14:32'),
    ('gangnam', '2026-0007', '김예린', '2012-09-18', '2026-07-30', '긴급상담', NULL, '보호자 입원으로 긴급 상담', '할머니가 입원해 혼자 지내게 됨. 친척과 연락해 임시 보호를 조율하고 식사 지원을 연계함.', 'demo1@demo-gangnam.eumi.test', '2026-07-30 18:53'),
    ('gangnam', '2026-0007', '김예린', '2012-09-18', '2026-08-03', '기타', '사례회의', '통합사례회의', '주민센터 · 정신건강복지센터와 사례회의를 열어 역할을 나눔. 이 기관은 정기 방문과 자원 연계를, 주민센터는 공적 급여 신청을 맡기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-08-03 15:48'),
    ('gangnam', '2026-0007', '김예린', '2012-09-18', '2026-08-14', '정기상담', NULL, '정기 상담', '학교에 다시 꾸준히 나가는 중. 할머니 병원 동행은 동행 서비스로 대신하기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-08-14 13:33'),
    ('gangnam', '2026-0007', '김예린', '2012-09-18', '2026-09-18', '정기상담', NULL, '학교 · 가정 연계 상담', '담임교사와 통화해 출결 상황을 공유함. 청소년상담복지센터 상담과 온라인 학습 지원을 연계함.', 'demo1@demo-gangnam.eumi.test', '2026-09-18 18:54'),
    ('gangnam', '2026-0008', '이소연', '1999-03-11', '2026-04-17', '초기상담', NULL, '청년 1인가구 생활고 상담', '고시원에 사는 청년. 아르바이트가 끊겨 월세가 두 달 밀림. 학자금 대출 상환 독촉을 받고 있으며 식비를 아끼려고 하루 한 끼만 먹는다고 함.', 'demo1@demo-gangnam.eumi.test', '2026-04-17 13:13'),
    ('gangnam', '2026-0008', '이소연', '1999-03-11', '2026-07-03', '긴급상담', NULL, '퇴거 통보', '월세 체납으로 이번 달 말까지 방을 비우라는 통보를 받음. 긴급 주거비를 신청하고 임시 거처를 함께 알아봄.', 'demo1@demo-gangnam.eumi.test', '2026-07-03 18:56'),
    ('gangnam', '2026-0008', '이소연', '1999-03-11', '2026-09-28', '정기상담', NULL, '주거 · 금융 지원 연계', '청년 월세 지원과 재무상담을 안내하고 신청을 도움. 푸드뱅크 이용을 연계함.', 'demo1@demo-gangnam.eumi.test', '2026-09-28 18:55'),
    ('gangnam', '2026-0009', '황병철', '1950-07-22', '2026-04-17', '초기상담', NULL, '독거 어르신 안부 확인 첫 방문', '다세대 주택 반지하에서 혼자 지내는 어르신. 자녀와는 연락이 뜸하고 최근 몇 달 사이 외출이 크게 줄었다고 함. 무릎과 허리 통증으로 장보기가 어려워 끼니를 자주 거름. 방문을 반기며 정기 방문에 동의함.', 'demo1@demo-gangnam.eumi.test', '2026-04-17 18:42'),
    ('gangnam', '2026-0009', '황병철', '1950-07-22', '2026-05-07', '기타', '사례회의', '통합사례회의', '주민센터 · 정신건강복지센터와 사례회의를 열어 역할을 나눔. 이 기관은 정기 방문과 자원 연계를, 주민센터는 공적 급여 신청을 맡기로 함.', 'demo2@demo-gangnam.eumi.test', '2026-05-07 13:23'),
    ('gangnam', '2026-0009', '황병철', '1950-07-22', '2026-10-05', '정기상담', NULL, '정기 안부 방문', '건강 상태는 지난 방문과 비슷함. 반찬 지원을 이어가고 복지관 프로그램 일정을 다시 안내함. 다음 방문 날짜를 달력에 적어 드림.', 'demo1@demo-gangnam.eumi.test', '2026-10-05 15:48'),
    ('gangnam', '2026-0010', '김지호', '2009-03-07', '2026-05-11', '초기상담', NULL, '조손가정 청소년 상담', '할머니와 둘이 사는 청소년. 학교 결석이 잦아 담임교사가 의뢰함. 할머니 건강이 나빠져 집안일과 병원 동행을 대신 하고 있음.', 'demo1@demo-gangnam.eumi.test', '2026-05-11 13:39'),
    ('gangnam', '2026-0010', '김지호', '2009-03-07', '2026-10-05', '정기상담', NULL, '정기 상담', '학교에 다시 꾸준히 나가는 중. 할머니 병원 동행은 동행 서비스로 대신하기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-10-05 15:07'),
    ('gangnam', '2026-0010', '김지호', '2009-03-07', '2026-10-19', '기타', '가족상담', '가족과 돌봄 계획 논의', '가족과 통화해 그간 상황을 공유함. 가족이 한 달에 한 번 방문하고 주 1회 전화하기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-10-19 13:15'),
    ('gangnam', '2026-0010', '김지호', '2009-03-07', '2026-11-02', '종료상담', NULL, '사례 종결 상담', '친척이 함께 살게 되고 학교생활이 안정되어 종결.', 'demo1@demo-gangnam.eumi.test', '2026-11-02 17:42'),
    ('gangnam', '2026-0011', '송정자', '1954-05-28', '2026-05-11', '초기상담', NULL, '이웃 제보로 첫 방문', '같은 건물 이웃이 요즘 어르신이 보이지 않는다고 알려 와 방문. 배우자와 사별한 뒤 혼자 지내며 낮에도 커튼을 치고 TV만 본다고 함. 혈압약은 챙기고 있으나 식사량이 눈에 띄게 줄었음.', 'demo2@demo-gangnam.eumi.test', '2026-05-11 16:24'),
    ('gangnam', '2026-0011', '송정자', '1954-05-28', '2026-07-27', '긴급상담', NULL, '낙상 후 긴급 방문', '집 안에서 넘어져 손목을 다쳤다는 연락을 받고 방문. 병원 진료에 동행했고 골절은 아님. 회복 기간 동안 반찬 배달과 안부 전화를 매일로 늘림.', 'demo1@demo-gangnam.eumi.test', '2026-07-27 14:21'),
    ('gangnam', '2026-0011', '송정자', '1954-05-28', '2026-09-01', '정기상담', NULL, '정기 안부 방문', '건강 상태는 지난 방문과 비슷함. 반찬 지원을 이어가고 복지관 프로그램 일정을 다시 안내함. 다음 방문 날짜를 달력에 적어 드림.', 'demo2@demo-gangnam.eumi.test', '2026-09-01 14:35'),
    ('gangnam', '2026-0012', '정정숙', '1951-06-17', '2026-05-11', '초기상담', NULL, '주거환경 악화 가구 첫 방문', '집 안에 물건과 쓰레기가 쌓여 악취가 난다는 이웃 민원으로 방문. 혼자 사는 어르신으로 물건을 버리는 것을 강하게 거부함. 화재 위험이 있어 단계적으로 정리하기로 설득함.', 'demo2@demo-gangnam.eumi.test', '2026-05-11 14:01'),
    ('gangnam', '2026-0012', '정정숙', '1951-06-17', '2026-06-08', '정기상담', NULL, '정리 후 유지 점검', '정리한 공간이 대체로 유지되고 있음. 주 1회 방문해 함께 정리 상태를 확인하기로 함.', 'demo2@demo-gangnam.eumi.test', '2026-06-08 14:57'),
    ('gangnam', '2026-0012', '정정숙', '1951-06-17', '2026-08-19', '정기상담', NULL, '주거환경 정리 1차', '본인 동의를 받아 부엌과 현관부터 정리. 버릴 물건은 본인이 직접 고르게 함. 정리 후 숨이 좀 쉬어진다고 함.', 'demo2@demo-gangnam.eumi.test', '2026-08-19 16:51'),
    ('gangnam', '2026-0012', '정정숙', '1951-06-17', '2026-09-17', '기타', '가족상담', '가족과 돌봄 계획 논의', '가족과 통화해 그간 상황을 공유함. 가족이 한 달에 한 번 방문하고 주 1회 전화하기로 함.', 'demo2@demo-gangnam.eumi.test', '2026-09-17 15:12'),
    ('gangnam', '2026-0012', '정정숙', '1951-06-17', '2026-10-26', '중기상담', NULL, '정신건강 상담 연계 점검', '저장 행동에 대해 정신건강복지센터 상담을 받기 시작함. 이웃과의 갈등이 줄었음.', 'demo1@demo-gangnam.eumi.test', '2026-10-26 17:11'),
    ('gangnam', '2026-0013', '박준서', '2009-05-26', '2026-05-12', '초기상담', NULL, '조손가정 청소년 상담', '할머니와 둘이 사는 청소년. 학교 결석이 잦아 담임교사가 의뢰함. 할머니 건강이 나빠져 집안일과 병원 동행을 대신 하고 있음.', 'demo1@demo-gangnam.eumi.test', '2026-05-12 18:18'),
    ('gangnam', '2026-0013', '박준서', '2009-05-26', '2026-06-29', '정기상담', NULL, '학교 · 가정 연계 상담', '담임교사와 통화해 출결 상황을 공유함. 청소년상담복지센터 상담과 온라인 학습 지원을 연계함.', 'demo1@demo-gangnam.eumi.test', '2026-06-29 16:48'),
    ('gangnam', '2026-0013', '박준서', '2009-05-26', '2026-09-21', '긴급상담', NULL, '보호자 입원으로 긴급 상담', '할머니가 입원해 혼자 지내게 됨. 친척과 연락해 임시 보호를 조율하고 식사 지원을 연계함.', 'demo1@demo-gangnam.eumi.test', '2026-09-21 16:45'),
    ('gangnam', '2026-0014', '김하은', '1996-08-08', '2026-07-13', '초기상담', NULL, '청년 1인가구 생활고 상담', '고시원에 사는 청년. 아르바이트가 끊겨 월세가 두 달 밀림. 학자금 대출 상환 독촉을 받고 있으며 식비를 아끼려고 하루 한 끼만 먹는다고 함.', 'demo1@demo-gangnam.eumi.test', '2026-07-13 14:26'),
    ('gangnam', '2026-0014', '김하은', '1996-08-08', '2026-08-24', '정기상담', NULL, '주거 · 금융 지원 연계', '청년 월세 지원과 재무상담을 안내하고 신청을 도움. 푸드뱅크 이용을 연계함.', 'demo1@demo-gangnam.eumi.test', '2026-08-24 17:43'),
    ('gangnam', '2026-0015', '박영자', '1951-05-05', '2026-07-20', '초기상담', NULL, '치매 의심 어르신 첫 방문', '같은 물건을 반복해서 사 오고 가스불을 켜 둔 채 외출한 일이 있다는 이웃 제보. 혼자 사는 어르신으로 자녀는 멀리 살아 자주 오지 못함.', 'demo1@demo-gangnam.eumi.test', '2026-07-20 14:36'),
    ('gangnam', '2026-0015', '박영자', '1951-05-05', '2026-08-19', '정기상담', NULL, '치매 선별검사 연계', '치매안심센터 선별검사에 동행함. 정밀검사가 필요하다는 결과가 나와 자녀와 일정을 조율함.', 'demo1@demo-gangnam.eumi.test', '2026-08-19 16:14'),
    ('gangnam', '2026-0015', '박영자', '1951-05-05', '2026-09-25', '정기상담', NULL, '안전 점검 방문', '가스 자동차단기를 설치하고 약 달력을 드림. 생활지원사 방문 횟수를 늘림.', 'demo1@demo-gangnam.eumi.test', '2026-09-25 18:33'),
    ('gangnam', '2026-0015', '박영자', '1951-05-05', '2026-10-13', '중기상담', NULL, '진단 후 돌봄 계획 점검', '경도 치매 진단을 받음. 치매안심센터 인지 프로그램에 주 2회 참여 중이며 자녀가 주말마다 방문하기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-10-13 17:54'),
    ('gangnam', '2026-0016', '서정숙', '1944-02-05', '2026-07-21', '초기상담', NULL, '독거 어르신 안부 확인 첫 방문', '원룸에서 혼자 지내는 어르신. 자녀와는 연락이 뜸하고 최근 몇 달 사이 외출이 크게 줄었다고 함. 무릎과 허리 통증으로 장보기가 어려워 끼니를 자주 거름. 방문을 반기며 정기 방문에 동의함.', 'demo1@demo-gangnam.eumi.test', '2026-07-21 16:11'),
    ('gangnam', '2026-0016', '서정숙', '1944-02-05', '2026-08-24', '정기상담', NULL, '전화 안부 확인', '전화로 안부 확인. 날씨 때문에 외출을 줄였다고 함. 난방과 식사 상태를 확인하고 다음 주 방문을 약속함.', 'demo1@demo-gangnam.eumi.test', '2026-08-24 14:46'),
    ('gangnam', '2026-0017', '김영철', '1978-09-13', '2026-08-17', '초기상담', NULL, '중장년 1인가구 첫 상담', '다세대 주택 반지하에 혼자 사는 중장년 남성. 사업을 접은 뒤 일용직을 전전하다 최근 몇 달은 일이 끊김. 하루 대부분을 집에서 보내고 끼니는 라면으로 때움. 가족과는 연락하지 않는다고 함.', 'demo2@demo-gangnam.eumi.test', '2026-08-17 14:24'),
    ('gangnam', '2026-0017', '김영철', '1978-09-13', '2026-09-02', '정기상담', NULL, '구직 상담 연계', '고용센터 중장년 취업 상담 예약을 함께 잡음. 이력서 작성을 어려워해 다음 방문 때 같이 쓰기로 함.', 'demo2@demo-gangnam.eumi.test', '2026-09-02 15:34'),
    ('gangnam', '2026-0018', '이동현', '1975-03-06', '2026-08-18', '초기상담', NULL, '중장년 1인가구 첫 상담', '임대아파트에 혼자 사는 중장년 남성. 사업을 접은 뒤 일용직을 전전하다 최근 몇 달은 일이 끊김. 하루 대부분을 집에서 보내고 끼니는 라면으로 때움. 가족과는 연락하지 않는다고 함.', 'demo1@demo-gangnam.eumi.test', '2026-08-18 17:48'),
    ('gangnam', '2026-0018', '이동현', '1975-03-06', '2026-09-11', '정기상담', NULL, '생활 상황 점검', '식사와 수면 상태를 확인함. 긴급복지 생계지원 신청을 도왔고 결과를 함께 기다리기로 함. 주 1회 안부 전화에 동의.', 'demo2@demo-gangnam.eumi.test', '2026-09-11 18:57'),
    ('gangnam', '2026-0018', '이동현', '1975-03-06', '2026-09-18', '긴급상담', NULL, '음주 후 연락 두절', '이틀째 연락이 되지 않아 방문하니 과음 후 누워 있었음. 의식은 있었고 진료에 동행함. 절주 상담 연계를 다시 권함.', 'demo2@demo-gangnam.eumi.test', '2026-09-18 13:59'),
    ('gangnam', '2026-0018', '이동현', '1975-03-06', '2026-10-19', '정기상담', NULL, '구직 상담 연계', '고용센터 중장년 취업 상담 예약을 함께 잡음. 이력서 작성을 어려워해 다음 방문 때 같이 쓰기로 함.', 'demo1@demo-gangnam.eumi.test', '2026-10-19 13:44'),
    ('gangnam', '2026-0019', '윤현우', '2006-11-03', '2026-08-31', '초기상담', NULL, '가족 의뢰로 시작한 은둔 청년 상담', '부모와 함께 살지만 1년 넘게 방에서 거의 나오지 않음. 낮과 밤이 바뀐 생활을 하며 가족과 대화가 끊김. 부모 상담부터 시작하기로 함.', 'demo2@demo-gangnam.eumi.test', '2026-08-31 16:16'),
    ('gangnam', '2026-0019', '윤현우', '2006-11-03', '2026-10-08', '정기상담', NULL, '방문 상담', '처음으로 얼굴을 보고 이야기함. 방 정리가 되어 있지 않아 함께 정리 계획을 세움. 청년 지원 프로그램 안내지를 전달.', 'demo1@demo-gangnam.eumi.test', '2026-10-08 15:08'),
    ('gangnam', '2026-0019', '윤현우', '2006-11-03', '2026-11-02', '종료상담', NULL, '사례 종결 상담', '아르바이트를 시작하고 청년 모임에 꾸준히 참여 중. 본인이 이제 혼자 해 보겠다고 해 종결. 청년센터 연락처를 다시 안내함.', 'demo2@demo-gangnam.eumi.test', '2026-11-02 15:21')
) AS s(org_key, management_no, name, birth_date, consulted_at, category, category_etc, purpose, content, recorder_email, created_at)
JOIN seed_demo_org o ON o.org_key = s.org_key
JOIN case_record c ON c.org_id = o.org_id AND c.management_no = s.management_no AND c.name = s.name AND c.birth_date = s.birth_date::date
JOIN member m ON m.email_normalized = s.recorder_email AND m.org_id = o.org_id
WHERE NOT EXISTS (
    SELECT 1 FROM consultation x
    WHERE x.case_id = c.case_id AND x.consulted_at = s.consulted_at::date AND x.purpose = s.purpose);
